/** Lazy probe for the additive key/value signed-range lane kernel ABI; a legacy binary keeps its older exports. */
private static final class NativeLaneKernel {
    private static final boolean AVAILABLE = available();
    private static boolean available() {
        if (!NativeLibrary.AVAILABLE) return false;
        try {
            return laneKernelAbiNative() == 1;
        } catch (UnsatisfiedLinkError legacyBinary) {
            return false;
        }
    }
}

private static native int laneKernelAbiNative();

/* ABI probe for the additive key/value signed-range lane kernel (recipe entryless-lane-kernel-20261106);
 * older m3_collections_mask binaries keep their existing exports and the Java lane paths stay exact.
 */
JNIEXPORT jint JNICALL
Java_jdk_m3_collections_M3IndexMaskCompactor_laneKernelAbiNative(JNIEnv *env, jclass owner) {
    (void)env; (void)owner;
    return 1;
}
